package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.regex.*;
/** Source contracts only; no live actions or native evidence. */
public class NativeProgressScanWiringTest {
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java"));}
 private String between(String s,String a,String b){return s.substring(s.indexOf(a),s.indexOf(b,s.indexOf(a)));}
 @Test public void immutableIndependentBudget(){assertEquals(3,RootProgressScanScope.MAX_FRAMES);assertEquals(2,RootProgressScanScope.MAX_SWIPES);assertEquals(15,RootProgressScanScope.SOURCE_TASK_ID);assertNotEquals(RootProgressReadScope.DIRECTORY,RootProgressScanScope.DIRECTORY);assertFalse(RootProgressScanScope.current(RootProgressScanScope.EXPIRES_UTC));}
 @Test public void everyOldLiveIssuerIsBlocked()throws Exception{
  Matcher m=Pattern.compile("static [\\w.<>]+ (issue\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(source("VisibleCaptureAuthority"));int n=0,alignment=0;
  while(m.find()){
   if(m.group(1).equals("issueAlignment")){alignment++;continue;} // Independently checked by UiImageAlignmentEntryTest.
   if(m.group(1).equals("issueProgressScanIntent")||m.group(1).equals("issueProgressScanFrame")||m.group(1).equals("issueProgressLocateIntent")||m.group(1).equals("issueProgressLocateFrame")||m.group(1).equals("issueCheckpointIntent")||m.group(1).equals("issueCheckpointFrame")||m.group(1).equals("issueProgressLocateIntent")||m.group(1).equals("issueProgressLocateFrame"))continue;
   assertTrue(m.group(1),m.group(2).contains("if(RootProgressScanScope.ACTIVE)throw"));n++;
  }
  assertTrue(n>=19);assertEquals(1,alignment);
 }
 @Test public void everyOldLiveStartIsBlocked()throws Exception{Matcher m=Pattern.compile("(?m)^    static CaptureSessionRuntime (start\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(source("CaptureSessionRuntime"));int n=0;while(m.find()){if(m.group(1).equals("startProgressScan")||m.group(1).equals("startCheckpointRead")||m.group(1).equals("startProgressLocate"))continue;assertTrue(m.group(1),m.group(2).contains("if(RootProgressScanScope.ACTIVE)throw"));n++;}assertTrue(n>=15);}
 @Test public void cluesAndUnhealthyStopBeforeActorConstruction()throws Exception{String s=between(source("CaptureSessionRuntime"),"private boolean advanceProgressScan(","private static final class ScanContinuation");for(String token:new String[]{"if(!healthy)","!progress.scanRowsUsable()","if(progress.scanClue())","returnReadIndex>=(returnReadIntent.progressLocate()?RootProgressLocateScope.MAX_FRAMES:RootProgressScanScope.MAX_FRAMES)","if(unpresented)"})assertTrue(token,s.indexOf(token)<s.indexOf("ReviewShizukuSwipeActor.forProgressScan"));assertTrue(s.contains("HEALTHY_UNPRESENTED_NO_SWIPE"));}
 @Test public void exactSourceAndDurableBurnBeforeFixedDispatch()throws Exception{String s=between(source("CaptureSessionRuntime"),"private boolean advanceProgressScan(","private static final class ScanContinuation");assertTrue(s.contains("if(!scanFreshSource(metadata))"));assertTrue(s.contains("RootProgressScanScope.burnScroll("));assertTrue(s.contains("permit.burn(requestOwner"));assertTrue(s.contains("exact==target&&scanFreshSource(metadata)&&permit.current"));assertTrue(s.contains("scroll.commandExitZero()"));assertTrue(s.contains("scanActor.knownClean()"));}
 @Test public void laterAcquisitionMustBeStrictlyAfterConfirmedScroll()throws Exception{String s=source("CaptureSessionRuntime");assertTrue(s.contains("rootLower<=returnReadIntent.scanBoundary()"));String i=source("RootReturnReadIntent");assertTrue(i.contains("if(result.commandExitZero()){scrollConfirmed++;scanAfter=now;}"));assertTrue(i.contains("scrollReserved[afterFrame-1]"));assertTrue(i.contains("scrollReserved[afterFrame-1]=true"));}
 @Test public void scanContinuationDoesNotWeakenLegacyBlankContinuation()throws Exception{String s=source("CaptureSessionRuntime");assertTrue(s.contains("scan==null?!intent.scanNavigation():scan.consume(intent,now)"));assertTrue(s.contains("new ReturnReadCompletion(this,new ScanContinuation(this))"));String c=between(s,"private static final class ScanContinuation","private void closeReturnReadOnOwner");for(String v:new String[]{"spent.compareAndSet(false,true)","intent==run.returnReadIntent","intent.scanNavigation()&&intent.live()","run.scanContinuable&&run.released&&run.reportFinal","!run.cancelled.get()","boundary==intent.scanBoundary()"})assertTrue(v,c.contains(v));}
 @Test public void noNewTaskTapBackOrTypingPath()throws Exception{String s=between(source("CaptureSessionRuntime"),"private boolean advanceProgressScan(","private static final class ScanContinuation");for(String bad:new String[]{"TapActor","BackActor","NativeRewardCardSession",".tap(",".back(","input text"})assertFalse(bad,s.contains(bad));assertTrue(s.contains("Thread.sleep(500)"));assertTrue(s.contains("never evidence of readiness or movement"));}
 @Test public void onlyNewVisibleChoicePrecedesOldScanlessPath()throws Exception{String s=source("DormantCaptureConfirmationActivity");String choice=s.substring(s.indexOf("private void showCaptureChoices()"));assertTrue(choice.indexOf("RootProgressScanScope.ACTIVE")<choice.indexOf("RootProgressReadScope.ACTIVE"));assertTrue(choice.contains("this::confirmProgressScan,this::cancelAndFinish);return;"));}
 @Test public void scrollBurnUsesCreateNewAndIndependentSlots()throws Exception{String s=source("RootProgressScanScope");assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("burn(files,\"SCROLL_\"+afterFrame"));assertTrue(s.contains("afterFrame>MAX_SWIPES"));assertFalse(s.contains("TRUNCATE_EXISTING"));}
 @Test public void nativeFrameAgeIsRecheckedAfterBlockingDispatchWork()throws Exception{String s=between(source("CaptureSessionRuntime"),"private boolean advanceProgressScan(","private static final class ScanContinuation");assertTrue(s.contains("exact!=target||!rootPreflightFresh()||!permit.burn"));String gate=between(s,"public boolean stillValid(","});");assertTrue(gate.indexOf("scanFreshSource(metadata)")<gate.indexOf("rootPreflightFresh()"));assertTrue(gate.contains("rootPreflightFresh()&&rootCurrent()&&activity.rootHiddenScalar()"));assertTrue(source("CaptureSessionRuntime").contains("rootCurrent()&&NativeProgressPublication.frameFresh(now,rootLower)"));}
 @Test public void scanTypedOverrideCannotBorrowLegacyContinuation()throws Exception{String s=source("CaptureSessionRuntime");int old=s.indexOf("ReturnReadCompletion next=unpresented&&released");int override=s.indexOf("if(returnReadIntent.scanNavigation())next=scanContinuable?new ReturnReadCompletion(this,new ScanContinuation(this)):null;",old);assertTrue(old>=0);assertTrue(override>old);assertTrue(override<s.indexOf("activity.returnReadFrameFinished(this,next,details)",old));}
}
